<?php
declare(strict_types=1);
namespace App\Interface\Http\Taxonomy;
use App\Application\Identity\Service\AuthService;use App\Application\Study\Port\TransactionManagerInterface;use App\Application\Taxonomy\Mapper\TaxonomySubjectResponseMapper;use App\Application\Taxonomy\Service\CreateTaxonomySubjectService;use App\Application\Taxonomy\Service\ListTaxonomySubjectsService;use App\Domain\Taxonomy\Service\SubjectTaxonomyService;use App\Infrastructure\Http\ApiResponseFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineEntityManagerFactory;use App\Infrastructure\Persistence\Doctrine\DoctrineTransactionManager;use App\Infrastructure\Persistence\Doctrine\Taxonomy\DoctrineTaxonomySubjectRepository;use App\Interface\Http\Identity\IdentityRequestFactory;use App\Interface\Http\Taxonomy\Controller\TaxonomyController;use InvalidArgumentException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;use Slim\App;
final class TaxonomyRouteRegistrar { public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){} public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$subjects=new DoctrineTaxonomySubjectRepository($em);$controller=new TaxonomyController($this->auth,new CreateTaxonomySubjectService($subjects,new SubjectTaxonomyService(),new TaxonomySubjectResponseMapper(),new DoctrineTransactionManager($em)),new ListTaxonomySubjectsService($subjects,new TaxonomySubjectResponseMapper()),$this->responses);$identity=new IdentityRequestFactory();$factory=new TaxonomyRequestFactory();$responses=$this->responses;$app->get('/v1/admin/taxonomy/subjects',static function(ServerRequestInterface $request,ResponseInterface $response)use($controller,$identity,$factory,$responses):ResponseInterface{try{return $controller->list($request,$response,$identity->accessToken($request),$factory->list($request));}catch(InvalidArgumentException $e){return $responses->problem($response,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$request->getAttribute('request_id'));}});$app->post('/v1/admin/taxonomy/subjects',static function(ServerRequestInterface $request,ResponseInterface $response)use($controller,$identity,$factory,$responses):ResponseInterface{try{return $controller->create($request,$response,$identity->accessToken($request),$factory->create($request));}catch(InvalidArgumentException $e){$missing=str_contains($e->getMessage(),'Token de acesso');return $responses->problem($response,$missing?'UNAUTHENTICATED':'VALIDATION_FAILED',$missing?'Credenciais invalidas ou expiradas.':'Um ou mais campos sao invalidos.',$missing?401:422,(string)$request->getAttribute('request_id'),[['field'=>'request','code'=>'INVALID_VALUE','message'=>$e->getMessage()]]);}});} }
